def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_capacity = bins - item
    remaining_capacity = np.maximum(remaining_capacity, 0)
    ideal_remaining = np.mean(bins) * 0.6  # Target ideal remaining capacity (60% of average bin capacity)
    return 1.0 / (1 + np.abs(remaining_capacity - ideal_remaining))
